import re
from decimal import Decimal, InvalidOperation

def american_probability(value):
    # Handle string inputs
    if isinstance(value, str):
        value = value.strip()
        if not value:
            raise ValueError("Empty string")
        try:
            # Try to convert to int or float
            if '.' in value:
                num = float(value)
            else:
                num = int(value)
        except (ValueError, OverflowError):
            raise ValueError("Invalid numeric string")
    elif isinstance(value, (int, float)):
        num = value
    else:
        raise ValueError("Invalid type")

    # Check if it's a finite number with absolute value >= 100
    if not (isinstance(num, (int, float)) and num.is_finite() and abs(num) >= 100):
        raise ValueError("Value must be a finite number with absolute value >= 100")

    # Check for bool or None
    if isinstance(num, bool) or num is None:
        raise ValueError("Invalid type")

    if num > 0:
        return 100 / (num + 100)
    else:
        return -num / (-num + 100)
